using System;
using System.Linq;
using UnityEngine;
namespace BWVR {
public sealed partial class PlayerRhythm {
 readonly VillagerExploration[] echoAudience=new VillagerExploration[2];readonly Vector3[] echoSpots=new Vector3[2];IslandDiscoveries echoWorld;VillagerExploration[] echoNeighbors=Array.Empty<VillagerExploration>();float nextAudience;
 public int AudienceSession{get;private set;}public int AudienceCount=>echoAudience.Count(p=>p!=null);
 public CreatureHybrid Creature=>god;
 public bool AudienceOpen=>god!=null&&Reserved&&count==4&&!item.held&&affordance.host==null&&!shared.Active&&!god.Season.paused&&god.State.time<expires;
 void ConfigureEchoAudience(){echoWorld=god.GetComponentInParent<QuestSlice>().GetComponentInChildren<IslandDiscoveries>();echoNeighbors=god.GetComponentInParent<QuestSlice>().GetComponentsInChildren<VillagerExploration>();}
 public bool ReserveEchoListener(VillagerExploration person,out Vector3 point){point=default;if(!AudienceOpen||person==null||echoAudience.Contains(person))return false;int slot=Array.IndexOf(echoAudience,null);if(slot<0)return false;var walker=person.GetComponent<IslandNavigator>();var nav=god.GetComponent<IslandNavigator>();var toward=god.transform.position-transform.position;toward.y=0;if(toward.sqrMagnitude<1e-10f)toward=-transform.forward;toward.Normalize();var side=Vector3.Cross(Vector3.up,toward);
  for(int i=0;i<6;i++){var wanted=transform.position+(side*(slot==0?1:-1)*(8+i)-toward*(4+i*.5f))*nav.world.Scale;if(!walker.CanPlace(wanted,out var at)||(echoWorld==null||!echoWorld.Reachable(person.transform.position,at,walker.profile)))continue;bool clear=true;for(int k=0;k<2;k++)if(echoAudience[k]!=null&&Vector3.Distance(at,echoSpots[k])<(walker.profile.radius+echoAudience[k].GetComponent<IslandNavigator>().profile.radius+.5f)*nav.world.Scale)clear=false;if(!clear||Vector3.Distance(at,god.transform.position)<(nav.profile.radius+walker.profile.radius+1)*nav.world.Scale)continue;echoAudience[slot]=person;echoSpots[slot]=point=at;return true;}return false;
 }
 public void ReleaseEchoListener(VillagerExploration person){for(int i=0;i<2;i++)if(echoAudience[i]==person)echoAudience[i]=null;}
 void AdvanceEchoAudience(){if(!AudienceOpen||Active&&Played>=2||god.State.time<nextAudience)return;nextAudience=god.State.time+.5f;foreach(var person in echoNeighbors.Where(p=>p!=null).OrderBy(p=>(p.transform.position-transform.position).sqrMagnitude)){if(AudienceCount>=2)break;person.TryWatchEcho(this);}}
 void EchoAudienceBeat(int note,int beat){foreach(var person in echoAudience)if(person!=null)person.EchoBeat(this,note,beat);}
 void FinishEchoAudience(bool success){var people=echoAudience.Where(p=>p!=null).ToArray();var happy=new System.Collections.Generic.List<VillagerExploration>(2);int visits=0;foreach(var person in people){int result=success?person.WitnessEcho(this):-1;if(result>=0){visits++;if(result>0)happy.Add(person);}else person.ResetTask();ReleaseEchoListener(person);}if(success&&god!=null){var memory=god.Season.WorldPlay.Echo;memory.audienceVisits=Math.Min(1000000,memory.audienceVisits+visits);foreach(var person in happy)foreach(var other in happy)if(person!=other)person.GetComponent<VillagerSocial>().Memory.RememberPeer(other.GetComponent<HybridTarget>().id,true,god.State.time);}}
}
// A short spectator intention on the established exploration motor, never a parallel actor loop.
public sealed partial class VillagerExploration {
 PlayerRhythm echoMusic;Vector3 echoSpot;int echoSession,echoNotes,echoLastBeat;float echoElapsed,echoSight,echoClap;bool echoArrived,echoSeen;
 public bool EchoAudience=>Current==Phase.EchoAudience;public int EchoBeats=>echoNotes;
 public bool CanSeeEcho(PlayerRhythm instrument){if(instrument==null||Vector3.Distance(transform.position,instrument.transform.position)>nav.world.Scale*24)return false;var resources=musicWorld!=null?musicWorld:(musicWorld=nav.world.GetComponentInChildren<VillageResources>());return resources!=null&&resources.ProvisionVisible(social,instrument.transform.position,instrument.transform);}
 public bool TryWatchEcho(PlayerRhythm instrument){if(!CanStartStructure||instrument==null||!instrument.AudienceOpen||social.Memory.injury>0||social.RecentFright||social.Memory.nextMusicAt>instrument.Creature.State.time||social.Memory.musicInterest+social.Memory.boldness*.2f<.4f||(!instrument.Creature.Season.developmentFocus&&!instrument.Creature.Season.Finished&&instrument.Creature.Season.water<45)||!CanSeeEcho(instrument)||!instrument.ReserveEchoListener(this,out var at))return false;echoMusic=instrument;echoSession=instrument.AudienceSession;echoSpot=at;echoElapsed=echoSight=echoClap=0;echoNotes=echoLastBeat=0;echoArrived=false;echoSeen=true;routine.BeginHandsFreeActivity();nav.ResetRoute();Current=Phase.EchoAudience;motion?.LookAt(instrument.transform);return true;}
 bool TickEchoAudience(float dt){if(echoMusic==null||!echoMusic.AudienceOpen||echoMusic.AudienceSession!=echoSession||social.Memory.injury>0||social.RecentFright||routine.BuildingCathedral||routine.Worshipping||echoElapsed>35){ResetTask();return false;}echoElapsed+=dt;echoSight-=dt;if(echoSight<=0){echoSight=.25f;echoSeen=CanSeeEcho(echoMusic);}if(!echoArrived){bool arrived=nav.MoveTo(echoSpot,transform.lossyScale.y*1.6f,dt);var delta=transform.position-echoSpot;delta.y=0;if(delta.magnitude<=nav.world.Scale*.5f){echoArrived=true;nav.ResetRoute();motion?.Activity(0);}else if(arrived||nav.Blocked&&echoElapsed>3){ResetTask();return false;}}
  if(echoArrived){var toward=echoMusic.transform.position-transform.position;toward.y=0;if(toward.sqrMagnitude>1e-10f)transform.rotation=Quaternion.RotateTowards(transform.rotation,Quaternion.LookRotation(toward),dt*150);echoClap=Mathf.Max(0,echoClap-dt);motion?.Clap(echoClap>0?Mathf.Sin((1-echoClap/.45f)*Mathf.PI):0);}motion?.LookAt(echoMusic.transform);return true;
 }
 public void EchoBeat(PlayerRhythm instrument,int note,int beat){if(!EchoAudience||echoMusic!=instrument||echoSession!=instrument.AudienceSession||!echoArrived||!echoSeen||actor.held||beat<=echoLastBeat||!CanSeeEcho(instrument))return;echoLastBeat=beat;echoNotes++;echoClap=.45f;}
 // -1 no visit, 0 exposed/disappointed, 1 comfortable. Only real witnessed completions count.
 public int WitnessEcho(PlayerRhythm instrument){if(!EchoAudience||echoMusic!=instrument||echoSession!=instrument.AudienceSession||!instrument.Completed||echoNotes<2||!echoArrived||actor.held||social.Memory.injury>0||social.RecentFright||!CanSeeEcho(instrument))return -1;var god=instrument.Creature;if(god.Season.paused)return -1;bool cover=construction!=null&&construction.sites.Any(site=>site.ShelteredAt(nav.profile.radius+.08f,nav.profile.height,transform.position));bool comfortable=god.Season.Weather.rain<.5f||cover;if(!social.Memory.RememberMusic(cover,god.Season.Weather.rain,god.State.time))return -1;RememberNearbyPlace(comfortable);if(comfortable){social.Memory.trust=Mathf.Clamp01(social.Memory.trust+.02f);social.Memory.affinity=Mathf.Clamp01(social.Memory.affinity+.01f);god.State.RememberBond(GetComponent<HybridTarget>().id,true);GetComponent<VillagerAffect>()?.EnjoyedMusic();}god.Journal.Add(god.State.time,"echo audience",CreatureAction.SocialInteraction,GetComponent<HybridTarget>().id,comfortable?"Clapped along with the creature's echo":"Rain spoiled an exposed performance");ResetTask();Current=Phase.Celebrate;motion?.Activity(0);if(comfortable)motion?.React();else motion?.Signal(false,true,instrument.transform.position);return comfortable?1:0;}
 void ReleaseEchoAudience(){var old=echoMusic;echoMusic=null;old?.ReleaseEchoListener(this);echoClap=0;echoArrived=echoSeen=false;motion?.Clap(0);motion?.LookAt(null);}
}
}
